export interface SwitchProps
  extends Omit<
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    "onChange" | "checked" | "defaultChecked" | "children"
  > {
  size?: SwitchSize
  checked?: boolean
  defaultChecked?: boolean
  onCheckedChange?: (checked: boolean) => void
  disabled?: boolean
  /** Sets aria-invalid; no visual treatment yet (no Figma State=invalid) */
  invalid?: boolean
  /** Shows a visible label linked via aria-labelledby */
  label?: React.ReactNode
  description?: React.ReactNode
  /** Whether the switch is required in a form context */
  required?: boolean
  /** Explicit id — falls back to React useId() */
  id?: string
}

/* ── Component ──────────────────────────────────────────────── */

export function Switch({
  size = "md",
  checked: controlledChecked,
  defaultChecked = false,
  onCheckedChange,
  disabled = false,
  invalid = false,
  label,
  description,
  required,
  id,
  ...rest
}: SwitchProps) {
  const generatedId = useId()
  const uid = id ?? generatedId
  const labelId = `${uid}-label`
  const descId = `${uid}-desc`

