/* =================================================================
   Atlas Switch — component styles
   All values reference semantic tokens only.
   No hex literals. No magic numbers. Logical properties throughout.
   ================================================================= */

/* ── Root wrapper ─────────────────────────────────────────────── */

.root {
  display: inline-flex;
  align-items: flex-start;
  gap: var(--atlas-spacing-3);
}

.root[data-disabled] {
  opacity: var(--atlas-opacity-disabled);
  cursor: not-allowed;
}

/* ── Track (the <button>) ─────────────────────────────────────── */

.track {
  flex-shrink: 0;
  border: none;
  padding: 0;
  border-radius: var(--atlas-radius-full);
  background-color: var(--atlas-background-muted); /* off state per spec */
  position: relative;
  cursor: pointer;
  outline: none;
  transition:
    background-color var(--atlas-duration-fast) var(--atlas-easing-standard);
}

.track[data-state="checked"] {
  background-color: var(--atlas-primary);
}

/* ── Hover states ─────────────────────────────────────────────── */

.track:hover:not([data-disabled])[data-state="unchecked"] {
  background-color: var(--atlas-background-subtle);
}

.track:hover:not([data-disabled])[data-state="checked"] {
  background-color: var(--atlas-primary-hover);
}

/*
  BUG-053 — dark mode inversion fix.
  In dark mode the background scale runs: background (neutral-950) →
  background-subtle (neutral-900) → background-muted (neutral-800, lightest).
  The resting unchecked track is background-muted (lightest) so hovering
  to background-subtle (darker) creates an inverted affordance.
  Override: lighten the resting colour slightly using color-mix instead of
  stepping toward a darker token.
*/
[data-theme="dark"] .track:hover:not([data-disabled])[data-state="unchecked"] {
  background-color: color-mix(in oklch, var(--atlas-background-muted) 80%, oklch(1 0 0));
}

/* ── Active / pressed state ───────────────────────────────────── */
/*
  BUG-020 — add :active pressed feedback for spec state matrix completeness.
  Unchecked active: matches hover token (sufficient feedback for the brief press).
  Checked active: one step deeper than hover.
*/

.track:active:not([data-disabled])[data-state="unchecked"] {
  background-color: var(--atlas-background-subtle);
}

.track:active:not([data-disabled])[data-state="checked"] {
  background-color: var(--atlas-primary-active);
}

[data-theme="dark"] .track:active:not([data-disabled])[data-state="unchecked"] {
  background-color: color-mix(in oklch, var(--atlas-background-muted) 70%, oklch(1 0 0));
}

.track[data-disabled] {
  cursor: not-allowed;
  pointer-events: none;
}

.track:focus-visible {
  outline: var(--atlas-border-width-2) solid var(--atlas-focus-ring);
  outline-offset: var(--atlas-spacing-0_5);
}

/* ── Touch target expansion (BUG-060) ────────────────────────── */
/*
  The visual track is 18px (sm) or 24px (md) — both below the 44px
  minimum touch target. On coarse-pointer (touchscreen) devices we
  expand the hit area via min-height and centre the track visually
  within the tappable region using align-items and display:flex.
  The wrapper .root is already inline-flex so this adds no layout cost.
*/

@media (pointer: coarse) {
  .track {
    min-height: var(--atlas-touch-min); /* 44 px tap target */
    display: flex;
    align-items: center;
  }
}

/* ── Sizes ────────────────────────────────────────────────────── */
/*
  Spec (Figma Switch 95:114, 2026-09-15):
    sm: 28 × 16 px   thumb: 12 × 12 px   checked translate: 12 px
    md: 36 × 20 px   thumb: 16 × 16 px   checked translate: 16 px

  Token map:
    28 px = spacing-6(24) + spacing-1(4) = calc  (sm track width)
    --atlas-spacing-4      = 16 px  (sm track height; md thumb; md checked translate)
    --atlas-spacing-3      = 12 px  (sm thumb; sm checked translate)
    --atlas-spacing-9      = 36 px  (md track width)
    --atlas-spacing-5      = 20 px  (md track height)
    --atlas-spacing-0_5    = 2 px   (inset on each side)
*/

.sm {
  width: calc(var(--atlas-spacing-6) + var(--atlas-spacing-1)); /* 28 px */
  height: var(--atlas-spacing-4);                               /* 16 px */
}

.md {
  width: var(--atlas-spacing-9);  /* 36 px */
  height: var(--atlas-spacing-5); /* 20 px */
}

/* ── Thumb ────────────────────────────────────────────────────── */

.thumb {
  display: block;
  position: absolute;
  border-radius: var(--atlas-radius-full);
  /*
   * BUG-019 — spec lists --atlas-background for thumb fill. However
   * --atlas-background resolves to neutral-950 in dark mode (near-black),
   * which would render as a dark thumb on a dark track — visually broken.
   * --atlas-foreground-on-brand = neutral-0 (pure white) in BOTH light and
   * dark themes, making it the correct semantic choice for a thumb that must
   * always appear as a white circle. This is a documented spec deviation.
   */
  background-color: var(--atlas-foreground-on-brand);
  box-shadow: var(--atlas-shadow-sm);
  /* Logical inset — RTL-safe starting position */
  inset-block-start: var(--atlas-spacing-0_5);
  inset-inline-start: var(--atlas-spacing-0_5);
  /* Spec: thumb glide uses duration-base + easing-emphasized */
  transition: transform var(--atlas-duration-base) var(--atlas-easing-emphasized);
}

.sm .thumb {
  width: var(--atlas-spacing-3);  /* 12 px */
  height: var(--atlas-spacing-3); /* 12 px */
}

.md .thumb {
  width: var(--atlas-spacing-4);  /* 16 px */
  height: var(--atlas-spacing-4); /* 16 px */
}

/*
  Checked — slide thumb toward inline-end.
  translate = track-width − thumb-width − 2×inset
  sm: 28 − 12 − 4 = 12 px = spacing-3
  md: 36 − 16 − 4 = 16 px = spacing-4
*/
.sm[data-state="checked"] .thumb {
  transform: translateX(var(--atlas-spacing-3));
}

.md[data-state="checked"] .thumb {
  transform: translateX(var(--atlas-spacing-4));
}

/* RTL — negate the translate */
[dir="rtl"] .sm[data-state="checked"] .thumb {
  transform: translateX(calc(-1 * var(--atlas-spacing-3)));
}

[dir="rtl"] .md[data-state="checked"] .thumb {
  transform: translateX(calc(-1 * var(--atlas-spacing-4)));
}

/* ── Reduced motion ───────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  .track,
  .thumb {
    transition: none;
  }
}

/* ── Label + description ──────────────────────────────────────── */

.content {
  display: flex;
  flex-direction: column;
  gap: var(--atlas-spacing-1);
}

.label {
  font-family: var(--atlas-font-sans);
  font-size: var(--atlas-font-size-sm);
  font-weight: var(--atlas-font-weight-medium);
  color: var(--atlas-foreground);
  /* BUG-017 — was magic number 1.4 */
  line-height: var(--atlas-line-height-snug);
  cursor: pointer;
}

.root[data-disabled] .label {
  cursor: not-allowed;
}

.description {
  font-family: var(--atlas-font-sans);
  font-size: var(--atlas-font-size-xs);
  color: var(--atlas-foreground-muted);
  /* BUG-017 — was magic number 1.4 */
  line-height: var(--atlas-line-height-snug);
}

