    --atlas-spacing-9      = 36 px  (md track width)
    --atlas-spacing-5      = 20 px  (md track height; lg thumb; lg checked translate)
    --atlas-spacing-6      = 24 px  (lg track height)
    --atlas-spacing-0_5    = 2 px   (inset on each side)
