  width: var(--atlas-spacing-9);  /* 36 px */
  height: var(--atlas-spacing-5); /* 20 px */
}

.lg {
  width: calc(var(--atlas-spacing-9) + var(--atlas-spacing-2)); /* 44 px */
  height: var(--atlas-spacing-6);                                /* 24 px */
}

